            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum and number of elements
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int n = nums.length;

    // Helper function to check if there exists a subset with a given sum
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = totalSum; j >= 0; j--) {
            dp[i][j] = dp[i - 1][j];
            if (j >= num) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - num];
            }
        }
    }

    // Check if there exists a subset with the same average
    for (int i = 1; i <= n / 2; i++) {
        if (dp[i][i * totalSum / n] && (totalSum * i) % n == 0) {
            return true;
        }
    }

    return false;
}

