public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0) {
        result.add(0);
    }
    for (int i = 1; i < 10; i++) {
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(i);
        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                int nextNum = num * 10 + lastDigit - 1;
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + lastDigit + 1;
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
        }
    }
    result.sort(null);
    return result;
}

