                    if (current[0] != '0' || c != '0') {
                        current[i] = c;
                        result.add(new String(current));
                    }
                }
            }
            return;
        }

        for (char[] pair : new char[][]{{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}}) {
            if (i == 0 && pair[0] == '0' && current.length != 1) {
                continue;
            }
            current[i] = pair[0];
            current[n - 1 - i] = pair[1];
            helper(n, i + 1, result, current);
        }
    }

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) != 0);
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return -1;
    if (n == 1) return 1;

    Set<Long> seen = new HashSet<>();
    PriorityQueue<Long> minHeap = new PriorityQueue<>();
    seen.add(1L);
    minHeap.offer(1L);

    long currentUgly = 0;
    int count = 0;

    int[] factors = {2, 3, 5};

    while (count < n) {
        currentUgly = minHeap.poll();
        count++;

        for (int factor : factors) {
            long nextUgly = currentUgly * factor;
            if (seen.add(nextUgly)) {
                minHeap.offer(nextUgly);
            }
        }
    }

    return (int) currentUgly;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int energy = 1;
    int currentLength = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLength++;
        } else {
            energy = Math.max(energy, currentLength);
            currentLength = 1;
        }
    }
    energy = Math.max(energy, currentLength);
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            result.add(i);
        }
        result.sort((a, b) -> {
            String s1 = String.valueOf(a);
            String s2 = String.valueOf(b);
            return s1.compareTo(s2);
        });
        return result;
    }

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> countMap = new HashMap<>();
    int sum = 0;
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedString = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        reversedString.append(reversedWord).append(" ");
    }

    return reversedString.toString().trim();
}
